"""Initialise a nested dictionary with two levels

    Parameters
    ----------
    first_level_keys : list
        First level data
    second_level_keys : list
        Data to add in nested dict

    Returns
    -------
    nested_dict : dict
        Nested 2 level dictionary
    """
def init_nested_dict_zero(first_level_keys: Any, second_level_keys: Any) -> object {
    nested_dict = {};
    for first_level_key in first_level_keys {
        nested_dict[first_level_key] = {};
        for second_level_key in second_level_keys {
            nested_dict[first_level_key][second_level_key] = 0;
        }
    }
    return nested_dict;
}

"""Make maybe list a list if it is not.

    :param maybe_list: A variable that may be a list.

    :returns: A list."""
def listify(maybe_list: Any) -> object {
    return [maybe_list] if not isinstance(maybe_list, `list) else maybe_list;
}

""" swap arr[axis] and arr[-1] """
def swap(arr: Any, axis: Any) -> object {
    return (arr[:axis] + [arr[-1]] + arr[(axis + 1):-1] + [arr[axis]]);
}

